export const COMMANDS: Record<CommandName, { tier: Tier; personOnly: boolean; summary: string }> = {
  "invoice_review.settings": { tier: "read", personOnly: false, summary: "Read whether new document line reviews are enabled." },
  "invoice_review.configure": { tier: "routine", personOnly: true, summary: "Enable line review for new documents. Turning it off retains validation on previously reviewed documents." },
  "document.review_get": { tier: "read", personOnly: false, summary: "Read review revisions, immutable extraction seed and validation, independent of vendor matching." },
  "document.review_save": { tier: "routine", personOnly: false, summary: "Save an incomplete or complete invoice review. Preserve source rows; exclude with a reason. Request IDs replay identical writes; stale versions conflict. Edits invalidate summary acceptance." },
  "document.review_preview": { tier: "read", personOnly: false, summary: "Validate review fields without saving, reserving or approving anything." },
  "document.review_accept_summary": { tier: "routine", personOnly: true, summary: "Accept a summary-only bill from the saved review with a reason. Preserves all rows in history; requires reviewed headers and source. Never approves or releases payment." },
  "notification.settings": { tier: "read", personOnly: false, summary: "Notification settings and whether a real email sender is configured." },
  "notification.configure": { tier: "routine", personOnly: true, summary: "Enable workflow email notices for currently actionable bills. Approval reminders start after 48 hours, daily thereafter, at most three." },
  "notification.list": { tier: "read", personOnly: false, summary: "Delivery history for one bill. Sent means accepted by the provider, not confirmed delivery." },
  "notification.queue": { tier: "routine", personOnly: false, summary: "Queue only due notifications for eligible people on the current pinned workflow step. Company opt-in required; deduplicated." },
  "notification.deliver": { tier: "routine", personOnly: false, summary: "Deliver a queued workflow notification after rechecking eligibility. No arbitrary recipient or content. Uncertain delivery is never automatically retried." },
  "vendor.create": { tier: "routine", personOnly: false, summary: "Create a vendor." },
  "vendor.update": { tier: "routine", personOnly: false, summary: "Change a vendor's name, email or payment terms. Send null to clear email or terms; leave a field out to keep it. Only a person can change name or email, since they decide which invoices match the vendor and where payment-detail invitations go." },
  "vendor.list": { tier: "read", personOnly: false, summary: "List vendors with their open bill count and amount, whether each has its own workflow (else it follows the organization default), and how many workflow proposals wait for a person." },
  "vendor.get": { tier: "read", personOnly: false, summary: "A vendor with its account numbers, the workflow its bills follow and any open workflow proposals." },
  "vendor.add_account": { tier: "routine", personOnly: false, summary: "Record an account number this vendor uses for you, optionally tied to a location (a job site, a store). Invoices quoting it are matched to this vendor and location." },
  "vendor.remove_account": { tier: "routine", personOnly: false, summary: "Remove an account number from a vendor, e.g. one recorded by mistake. Invoices quoting it no longer match this vendor by it." },
  "vendor.invite_payee": { tier: "confirmed", personOnly: true, summary: "Ask Mercury to email this vendor an invitation to supply payment details. Only a person may send it. Preview sends nothing. Completion proposes a payee; a person must still accept it. Uncertain delivery is never automatically retried." },
  "vendor.refresh_payee_invite": { tier: "routine", personOnly: false, summary: "Check a Mercury invitation. Once completed, propose its recipient for the vendor without accepting it. Payvy also checks open invitations itself every few minutes. If delivery was uncertain, a person can recover it by supplying the invitation ID from Mercury; the email and method must match." },
  "vendor.propose_payee": { tier: "routine", personOnly: false, summary: "Propose who this vendor's bills are paid to: a recipient already set up in the connected bank (see bank.recipients) and a method. The account's last four digits are shown for checking. Nothing changes until a person accepts it with vendor.accept_payee. Use this when a vendor's bank details change." },
  "vendor.create_recipient": { tier: "confirmed", personOnly: true, summary: "Create this vendor as a recipient in the connected Mercury account from bank details a person has, and propose it as the vendor's payee (a person still accepts it). Only a person may run it. Preview shows the last four and sends nothing. The numbers go to Mercury and are never stored. Prefer vendor.invite_payee, which keeps the numbers out of Payvy entirely. An unclear answer is never retried: check Mercury's recipients first." },
  "vendor.accept_payee": { tier: "routine", personOnly: true, summary: "Accept a payee proposal: this vendor's bills are paid to it from now on. Check the destination with the vendor first; changed bank details are the most common way AP fraud happens." },
  "vendor.decline_payee": { tier: "routine", personOnly: true, summary: "Decline a payee proposal." },
  "workflow.get": { tier: "read", personOnly: false, summary: "The workflow a vendor's bills follow (or, without vendor_id, the organization default): its steps, a Mermaid chart, where it comes from, and open proposals." },
  "workflow.propose": { tier: "routine", personOnly: false, summary: "Propose a workflow for a vendor, or without vendor_id for the organization default. Nothing changes until a person accepts it with workflow.accept. Steps run in order and the last is the only pay step. Bills already received keep the workflow they arrived under." },
  "workflow.accept": { tier: "routine", personOnly: true, summary: "Accept a workflow proposal. It applies to bills received from now on." },
  "workflow.decline": { tier: "routine", personOnly: true, summary: "Decline a workflow proposal." },
  "bill.create": { tier: "routine", personOnly: false, summary: "Enter a bill, optionally from an inbox document, or from some of its pages (pages): those are split into a new document filed with the bill, atomically, and the rest stays in the inbox. It follows the vendor's current workflow from now on. If this vendor already has a bill with the same invoice number (ignoring case, spaces, punctuation and leading zeros), the copy stacks on that bill instead of becoming a second payable one: same amount is a recorded resend, a different amount is a revision that blocks payment until a person accepts or rejects it. allow_duplicate instead makes a separate bill, and that choice is recorded." },
  "bill.list": { tier: "read", personOnly: false, summary: "List bills, newest first. Filter by state (open, rejected, void, paid), by where open bills stand (status: awaiting_approval, held, waiting_for, awaiting_release, ready_to_pay, released), by vendor, by invoice_number (compared the way duplicates are: ignoring case, spaces, punctuation and leading zeros), or to bills waiting on you (mine). Each bill says received_count (how many copies of its invoice arrived) and pending_revision_amount_cents when a revised copy awaits a decision." },
  "bill.get": { tier: "read", personOnly: false, summary: "A bill with its lines, its workflow progress step by step, approvals, signals and history, every copy of the invoice received for it (arrivals, oldest first, with received_count and any pending_revision awaiting a person's decision), and the page arrangement of its document it pinned. While it waits for approval, approval says whether you can give it and, if not, why and who else can." },
  "bill.revision_accept": { tier: "routine", personOnly: true, summary: "Accept a revised invoice stacked on this bill (person only): the latest copy's amount and lines become the payable ones, and the bill can be paid again. The prior version stays in the bill's stack, not payable. This prepares the bill; it is not approval." },
  "bill.revision_reject": { tier: "routine", personOnly: true, summary: "Reject a revised invoice stacked on this bill (person only): the bill keeps the amount it already carries, the revised copy stays in its stack, and the bill can be paid again." },
  "bill.approve": { tier: "routine", personOnly: true, summary: "Approve a bill at its current approval step. You must be one of that step's approvers. One person gives a bill one approval, so you can't approve a second step, or a step a later one needs you for; and when approval_rules has submitter_cannot_approve on, whoever entered the bill or uploaded its document can't approve it. A refusal says who else can. bill.get shows it in approval before you try." },
  "bill.reject": { tier: "routine", personOnly: true, summary: "Reject a bill: it will not be paid. Final." },
  "bill.signal": { tier: "routine", personOnly: false, summary: "Report that something outside Payvy happened for a bill, e.g. customer_funded when the customer has paid for this cost. A workflow's wait_for step waits for its signal. Name the bill by bill_id or by the external_ref it was created with." },
  "bill.release": { tier: "confirmed", personOnly: true, summary: "Release a bill for payment at its pay step. With a bank connected, this sends the payment through it to the vendor's accepted payee; the preview shows exactly what will be sent. Preview first; commit with the returned token." },
  "bill.auto_pay": { tier: "routine", personOnly: false, summary: "Pay a bill whose workflow pays automatically (status ready_to_pay) through the connected Mercury account, to the vendor's accepted payee. Payvy does this on its own within a minute of the bill getting there; run it to pay one now. A bill over the auto-pay limit (auto_pay.limits) is never paid this way; it waits for a person to release it. If the payment doesn't go, the bill waits for a person to release it and is never retried automatically." },
  "bill.mark_paid": { tier: "confirmed", personOnly: false, summary: "Record that a released or ready bill was paid outside Payvy (a check, a payment made in the bank's own app). Payments sent through the connected bank are recorded on their own. Preview first; commit with the returned token." },
  "bill.void": { tier: "confirmed", personOnly: true, summary: "Void a bill entered by mistake. It no longer counts for duplicate detection. Preview first; commit with the returned token." },
  "auto_pay.limits": { tier: "read", personOnly: false, summary: "The ceiling on automatic payments: the company's limit (the $5,000.00 default until a person sets one) and each vendor's own limit, which overrides the company's in either direction. A bill over the limit in force (the vendor's if set, else the company's) never pays automatically: it waits for a person to release it, whatever its workflow says." },
  "auto_pay.lower_limit": { tier: "routine", personOnly: true, summary: "Lower the company's auto-pay limit, or with vendor_id set, lower or remove one vendor's own limit, as long as the limit in force for it doesn't go up (removing an override is allowed here when the company's limit is no higher). Lowering the company's limit doesn't change vendors with their own. Bills over the new limit wait for a person to release them. Only a person may change a limit. Anything that raises the limit in force needs auto_pay.raise_limit." },
  "auto_pay.raise_limit": { tier: "confirmed", personOnly: true, summary: "Raise the company's auto-pay limit (vendors with their own limit keep it), or with vendor_id set a vendor's own limit above what applies to it now (it may be above the company's), or remove a vendor's own limit when the company's is higher (limit_cents null). Only a person may change a limit. The preview lists the bills that would start paying automatically; commit with the returned token." },
  "po.settings": { tier: "read", personOnly: false, summary: "Whether purchase orders are on for this company. Off (the default) refuses every po.* write and never blocks a payment; reads still work." },
  "po.configure": { tier: "routine", personOnly: true, summary: "Turn purchase orders on or off for the company (person only). When on, each vendor's settings decide whether its bills require a PO, applying at once to bills in flight. Turning them off lifts the payment gate; allocations stay on record." },
  "po.create": { tier: "routine", personOnly: false, summary: "Create a draft purchase order for a vendor. Nothing matches against it until a person activates it with po.activate." },
  "po.update": { tier: "routine", personOnly: true, summary: "Change a purchase order (person only). Editing a draft sets it up; editing an active PO creates a new revision and never releases existing allocations. Vendor, number and currency cannot change." },
  "po.activate": { tier: "routine", personOnly: true, summary: "Activate a draft purchase order (person only). Requires an owner and an authorized amount. Imported POs arrive as drafts and are activated this way; an import never activates." },
  "po.close": { tier: "routine", personOnly: true, summary: "Close an active purchase order (person only), with a reason: fulfilled, expired, settled outside Payvy, or superseded. Allocations already made stand and nothing is released implicitly; their bills wait (ineligible_po) until the allocation is reversed or permitted." },
  "po.cancel": { tier: "routine", personOnly: true, summary: "Cancel a draft or active purchase order (person only), with a reason. Allocations already made stand and nothing is released implicitly; their bills wait (ineligible_po) until the allocation is reversed or permitted." },
  "po.suspend": { tier: "routine", personOnly: true, summary: "Suspend an active purchase order (person only), with a reason: allocations already made stand, new ones are refused, and its bills wait (suspended_po) until po.reactivate or a scoped po.override." },
  "po.reactivate": { tier: "routine", personOnly: true, summary: "Reactivate a suspended purchase order (person only): it takes allocations again and its bills stop waiting on the suspension." },
  "po.get": { tier: "read", personOnly: false, summary: "A purchase order: lifecycle, billing progress, authorized/reserved/consumed/available, its current lines, revisions and allocation history." },
  "po.list": { tier: "read", personOnly: false, summary: "Purchase orders, optionally for one vendor, each with authorized/reserved/consumed/available (none on a closed or canceled PO) and billing progress." },
  "po.import": { tier: "routine", personOnly: false, summary: "Import a purchase order from another system by external source/id (idempotent). Always lands as a draft: a person activates it with po.activate. opening_consumed_cents records amounts already billed in the source system and is not counted twice on a re-import." },
  "po.vendor_settings": { tier: "read", personOnly: false, summary: "A vendor's purchase-order settings: whether its bills require a PO, and its overage caps (dollar and/or percentage in basis points). Caps are pinned onto each PO revision when it is made." },
  "po.set_vendor_settings": { tier: "routine", personOnly: true, summary: "Set a vendor's purchase-order settings (person only): whether its bills require a PO, and overage caps. Zero overage is the default; an absent cap is not configured, a cap of 0 is zero. Existing PO revisions keep the allowance pinned on them." },
  "po.policy_get": { tier: "read", personOnly: false, summary: "A vendor's PO policies in force (the enumerated registry): over_period (flag_only or require_full_cover), quantity_matching (flag_only or enforce), and the version. Version 0 is the defaults: flag; do not silently match." },
  "po.policy_set": { tier: "routine", personOnly: true, summary: "Set a vendor's PO policies (person only): a new immutable version supersedes the old; bills already created keep the version they pinned. Asking for what is already in force is refused. Agents may not set policy." },
  "po.match_preview": { tier: "read", personOnly: false, summary: "Which of a bill's vendor's active POs it could go against: available amounts, a proposed allocation and any exception (no PO, over available). Writes and reserves nothing." },
  "po.match_apply": { tier: "confirmed", personOnly: false, summary: "Reserve bill amounts against purchase orders. Atomic across every PO in the call: all affected POs are locked in a consistent order, the whole set is validated (active, vendor, available plus the revision's pinned allowance, total not over the bill), then everything reserves together or nothing does. Reserving is preparation, not approval." },
  "po.override": { tier: "confirmed", personOnly: true, summary: "Permit one bill's PO exception (person only, separate from vendor approval): bound to this bill, its current POs and allocations, the exception and an authorized excess amount, with a required reason. Relevant changes void it and need a new override. It does not create PO capacity or hide the excess." },
  "po.allocation_accept": { tier: "routine", personOnly: false, summary: "Accept a reserved allocation as part of preparing a bill: the amount moves from reserved to consumed. This is not bill approval." },
  "po.allocation_reverse": { tier: "routine", personOnly: false, summary: "Release a reserved or consumed allocation with a reason (match rejected, bill rejected, bill voided). Capacity returns by this reversal record; allocations are never deleted. A PO revision never releases an allocation." },
  "inbox.get": { tier: "read", personOnly: false, summary: "What is waiting on the caller: bills a step needs them to approve or release (action approve or release), and payee changes and workflow proposals a person must accept or decline. Agents see it too, to remind people." },
  "approval_rules.get": { tier: "read", personOnly: false, summary: "The company's approval rules. submitter_cannot_approve: whoever entered a bill or uploaded its document can't approve it (bills an agent entered are unaffected). One approval per person per bill always applies." },
  "approval_rules.set": { tier: "routine", personOnly: true, summary: "Turn submitter_cannot_approve on or off for the whole company. It applies to approvals from now on, including bills already waiting." },
  "person.list": { tier: "read", personOnly: false, summary: "Everyone who can sign in to the web app, with the actor name their actions are recorded under." },
  "person.add": { tier: "routine", personOnly: true, summary: "Let someone sign in to the web app with a link sent to their email. They act as the person named by actor, with every right a person has: approving, releasing payments, accepting payees and workflows." },
  "person.set_roles": { tier: "routine", personOnly: true, summary: "Set a person's company roles. Admin only; roles combine. Cannot remove the last sign-in admin. Changes take effect on their next command, including an existing session or person API key. Audit records old and new roles." },
  "person.remove": { tier: "routine", personOnly: true, summary: "Stop someone signing in, and sign them out everywhere. Their past actions stay on the record. Refused for yourself (someone else removes you) and for the last person who can sign in." },
  "org.get": { tier: "read", personOnly: false, summary: "This organization: its id, its name as people see it in the app and sign-in emails, and when it was created." },
  "org.update": { tier: "routine", personOnly: true, summary: "Rename the organization. The name is trimmed, 1 to 100 characters, and must differ from the current one. Bills, vendors and events are unchanged." },
  "bank.authorize": { tier: "routine", personOnly: true, summary: "Begin Ramp OAuth with read scopes. Returns a consent URL; the current bank remains active. Authorization expires after ten minutes." },
  "bank.complete_authorization": { tier: "routine", personOnly: true, summary: "Complete Ramp OAuth for the same person and company. Seals credentials but does not activate a connection. Never retry an unclear code exchange; start authorization again." },
  "bank.authorization": { tier: "read", personOnly: true, summary: "Read fresh Ramp entity and funding choices for your staged authorization. Choose an exact account and fingerprint before activation." },
  "bank.activate": { tier: "confirmed", personOnly: true, summary: "Select a staged Ramp connection for setup and payee mapping, explicitly replacing the current paying bank. Preview and confirm the exact account fingerprint and previous connection ID (null if none). Ramp sending and auto-pay remain disabled." },
  "bank.maintain": { tier: "routine", personOnly: false, summary: "Check or renew an existing Ramp grant when due. The background worker uses this command. It cannot authorize or activate connections, accept payees or send payments. Failures persist a bounded retry schedule or require reconnection. Preview sends nothing." },
  "bank.renew": { tier: "routine", personOnly: true, summary: "Check a live Ramp connection and renew access when needed. A person can resume checks paused after repeated temporary failures, once cooldown permits. Rejected grants require reconnecting. Preview sends nothing." },
  "bank.connect": { tier: "routine", personOnly: true, summary: "Connect a bank with an API token from its dashboard. Mercury pays bills: mode request (default) waits in Mercury for a Mercury admin (Custom token, RequestSendMoney scope); mode direct sends at once (Read and Write token, server IP allowlisted). Rho is always read-only (no mode to choose): it never pays and never replaces the paying bank; create its token in Rho Settings > API > Access Tokens with accounts:read and transactions:read. Payvy keeps tokens encrypted and never holds money or account numbers." },
  "bank.get": { tier: "read", personOnly: false, summary: "The selected bank and all live connections, with capabilities (pay, read_only, setup). Ramp includes connection health, retry time and recovery actions; setup never enables payments." },
  "bank.disconnect": { tier: "routine", personOnly: true, summary: "Disconnect a bank (the paying one by default, or provider rho for the read-only one). No new payments are sent through a disconnected paying bank; ones already sent are still tracked." },
  "bank.accounts": { tier: "read", personOnly: false, summary: "Accounts at the read-only Rho connection, with balances in cents. Empty object input; refuses when no Rho connection is live." },
  "bank.transactions": { tier: "read", personOnly: false, summary: "Transactions from the read-only Rho connection: signed amounts in cents (negative is money out), counterparty, status and posted time. Filter by account, date and search text." },
  "bank.recipients": { tier: "read", personOnly: false, summary: "Discover existing bank payees. Ramp lists vendors first; pass recipient_id to list specific ACH instruments, masked destinations and fingerprints for vendor.propose_payee. Never guess an instrument or enter bank numbers here." },
  "payment.list": { tier: "read", personOnly: false, summary: "Payments sent through the bank, newest first, or only those still waiting on the bank." },
  "payment.refresh": { tier: "routine", personOnly: false, summary: "Ask the bank where a payment stands now and record it: sent marks the bill paid; failed, cancelled or rejected sends the bill back for release; returned reopens a paid bill. Payvy does this on its own every minute or two." },
  "document.upload": { tier: "routine", personOnly: false, summary: "Add a file to the inbox: a PDF or image (PNG, JPEG, GIF, WebP, TIFF) of a bill, up to 25 MB, as base64. Its type is read from the file itself. Refused if the same file is already here, naming the existing document." },
  "document.list": { tier: "read", personOnly: false, summary: "Documents in the inbox (default), oldest first; or filed or trashed ones, or split ones (every page moved to other documents). A document split from another has split_from: its id and filename. Each says what its latest reading found (reading: vendor and how it matched, invoice_count, invoice_numbers, total_cents, dates, failed_checks, ready; null until read) and its cover: the first page shown, for a thumbnail." },
  "document.get": { tier: "read", personOnly: false, summary: "A document's details, every time a model read it (newest first, with checks, the suggested bill_input, and out_of_date when its pages were rearranged since), its pages (page count of the original file, the current arrangement and version, every earlier version, and whether they are locked and why), split_from (the document it was split from) and split_into (documents split from it, with their pages), its history, and a download link to the original file valid for 15 minutes. A reading of a file with several invoices has invoices: the pages, invoice number and total of each." },
  "document.extract": { tier: "routine", personOnly: false, summary: "Read an inbox document with the configured model: vendor, invoice number, dates, lines and total, checked against each other and matched to a vendor on file. Returns the checks, whether it is ready, and bill_input: the bill.create input it suggests, to enter as is or corrected. Nothing becomes a bill until bill.create. New documents are read automatically when the server's reader is on. Refused if the document was already read, unless again is true. The model gets the original file and, when the document is only some of its pages (split from it, or with pages hidden), is told which pages to read. When it finds several invoices in the file, the reading lists them (invoices) and fails the one_invoice check; an agent's reading then splits the file straight away into one document per invoice (split.to_read: read each next), which document.unsplit undoes. A person's reading only suggests. A document already split from another is never split again this way." },
  "document.arrange": { tier: "routine", personOnly: false, summary: "Set a document's page order, rotation and hidden pages in one change, as a new version of its arrangement; the original file never changes. List every page of this document once, by its page number in the original file, in the order to show them; at least one must stay visible. expected_version is the version from document.get: if someone changed the pages since, it is refused and you get the document again. Refused for a document set aside as not a bill, and once its bill has an approval or is no longer open (pages lock after approval). A bill still waiting for its first approval moves to the new version, and its history says so." },
  "document.split": { tier: "routine", personOnly: false, summary: "Move groups of pages into new documents, one per group, for a file holding several invoices. Each new document is a view of the same original file (nothing is copied), shows only its pages in the order given with their rotation, records which document it came from, and is in the inbox to be read and entered. The moved pages leave this document's next arrangement version; if none are left it becomes split and leaves the inbox. expected_version is pages.version from document.get. Refused for a document set aside or locked, for a stale version, for groups that overlap, name pages this document doesn't have, or would leave a new document with nothing to show. Takes effect at once; document.unsplit undoes it." },
  "document.create_bills": { tier: "routine", personOnly: true, summary: "Make a bill of each invoice in a file of several, in one request: the file is split at once (one new document per group of pages, as document.split does), and the server then reads each part and creates its bill in the background, as the person who asked. A part that reads cleanly becomes a bill; a copy of an invoice already here stacks on that bill (a resend, or a revision when the amount differs); any other part waits in To review for a person, with the reason. Pages in leftover are part of no bill and stay with this document. groups and leftover together must name every visible page once. request_id makes it safe to retry: the same request_id returns the batch already made instead of splitting again. document.get on this document shows the batch's progress (bill_batch)." },
  "document.unsplit": { tier: "routine", personOnly: false, summary: "Undo a split: a document split from another gives its pages back to it (in their original place where it can tell), and the other document comes back to the inbox if it had no pages left. The split document becomes split and leaves the inbox. Refused once the split document is filed with a bill or set aside, or when the document it came from is locked." },
  "document.trash": { tier: "routine", personOnly: false, summary: "Take a document out of the inbox because it isn't a bill (a statement, a marketing email, a duplicate). The file is kept." },
  "email.address": { tier: "read", personOnly: false, summary: "This organization's inbound address. Bills emailed or forwarded to it land in the document inbox; a +tag after the token is allowed (token+fuel@...). Null until a person creates one with email.new_address." },
  "email.new_address": { tier: "routine", personOnly: true, summary: "Create the inbound address, or replace it if it is getting spam. The old address stops working at once, so anyone forwarding to it must switch." },
  "email.import": { tier: "routine", personOnly: false, summary: "Read a raw email (an .eml file, base64) into the inbox: its PDF and image attachments become documents, including those of a forwarded email. The inbound webhook uses this too. Refused if the same email is already here. The result lists what was skipped and why." },
  "email.list": { tier: "read", personOnly: false, summary: "Emails received, newest first: sender, subject and what was skipped." },
  "email.get": { tier: "read", personOnly: false, summary: "One email: its details, the documents it brought in, and a 15-minute download link for the original message." },
  "ledger.connect": { tier: "confirmed", personOnly: true, summary: "Connect VisiBooks for this company (person only): its HTTPS origin, entity id and API key. The key is sealed at once and never read back; reconnecting updates the same connection, so its links stand. Confirmed, because it carries a credential." },
  "ledger.settings": { tier: "read", personOnly: false, summary: "The company's ledger connection: provider, origin, entity, when it posts (post_when), the AP account and the bank account map. Never the credential. Disconnected companies read connected: false." },
  "ledger.configure": { tier: "routine", personOnly: true, summary: "Change how the connected ledger posts (person only): post_when (approval or payment), the AP account, coding defaults, and the map from Payvy bank connections (or payment methods) to ledger bank accounts. Asking for what is already set is refused." },
  "ledger.post_bill": { tier: "routine", personOnly: false, summary: "Post one bill to the connected ledger. The same bill posted again returns the first ledger id and sends nothing. A changed bill after posting is a conflict. A rejected or void bill is refused. Preview sends nothing." },
  "ledger.post_payment": { tier: "routine", personOnly: false, summary: "Record one sent payment in the ledger, applied to its posted bill and drawn on the mapped ledger bank account. Payvy has already paid through the customer's bank. Preview sends nothing." },
  "ledger.void": { tier: "confirmed", personOnly: true, summary: "Void the ledger's copy of a bill. Every posted payment is voided first, oldest first, including one the bank later returned. If a payment void is refused the bill stays posted. This cannot be undone, so it asks for confirmation. Only a person with admin may do this. Preview sends nothing." },
  "event.list": { tier: "read", personOnly: false, summary: "The audit log, newest first: every change, who made it and when. Filter to one bill, vendor or proposal with entity_id." },
};
